def free_already_deleted(apps, schema_editor):
    """Intakes deleted before this existed: give their PLSM numbers back too,
    unless something (a booking, a shipment, another sheet) uses them now."""
    import re

    IntakeDeletion = apps.get_model("warehouse", "IntakeDeletion")
    IntakeSheet = apps.get_model("warehouse", "IntakeSheet")
    FreedReference = apps.get_model("warehouse", "FreedReference")
    Booking = apps.get_model("bookings", "Booking")
    Package = apps.get_model("accounts", "Package")

    for deletion in IntakeDeletion.objects.all():
        reference = (deletion.reference or "").strip().upper()
        if not re.fullmatch(r"PLSM-\d{5}", reference):
            continue
        in_use = (
            Booking.objects.filter(shipping_number__iexact=reference).exists()
            or IntakeSheet.objects.filter(reference__iexact=reference).exists()
            or Package.objects.filter(tracking_number__iexact=reference).exists()
        )
        if not in_use:
            FreedReference.objects.get_or_create(
                reference=reference,
                defaults={"freed_at": deletion.deleted_at, "freed_by_id": deletion.deleted_by_id},
            )


